/* PSG DNA — Parc navy night, the Hechter stripe, Ville Lumière gold */
.theme-psg {
  --bg: oklch(0.209 0.053 263.3);
  --surface: oklch(0.250 0.062 264.1);
  --surface-2: oklch(0.301 0.076 264.1);
  --fg: oklch(1.000 0 0);
  --fg-muted: oklch(0.704 0.054 264.1);
  --accent: oklch(0.575 0.213 29.6);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.730 0.101 81.1);
  --line: oklch(1 0 0 / 14%);
  --success: oklch(0.615 0.143 147.4);
  --warning: oklch(0.768 0.158 81.3);
  --danger: oklch(0.55 0.2 27);
  --radius: 0.375rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Prompt", sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0em;
  --label-transform: uppercase;
  --label-tracking: 0.16em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-psg h1,
.theme-psg h2,
.theme-psg h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-psg { --font-ui: var(--font-display); }
.theme-psg h1, .theme-psg h2 { text-transform: uppercase; }
.theme-psg button { text-transform: uppercase; letter-spacing: 0.06em; }

.theme-psg { background-image: linear-gradient(90deg, transparent 0 44%, oklch(1 0 0 / 7%) 44% 46%, oklch(0.5 0.18 25 / 30%) 46% 54%, oklch(1 0 0 / 7%) 54% 56%, transparent 56%); background-size: 100% 480px; background-repeat: no-repeat; }
.theme-psg h1 { font-weight: 600; letter-spacing: 0.04em; }
.theme-psg h1::after { content: ""; display: block; height: 4px; width: 6rem; margin-top: 0.7rem; background: linear-gradient(90deg, #0b1730 0 30%, #ffffff 30% 40%, var(--accent) 40% 60%, #ffffff 60% 70%, #0b1730 70%); outline: 1px solid oklch(1 0 0 / 25%); }

/* depth */
.theme-psg thead th { color: var(--accent-2); text-transform: uppercase; letter-spacing: 0.12em; font-size: 0.75em; border-bottom: 2px solid var(--accent); background: oklch(0.24 0.058 264); }
.theme-psg td { border-bottom: 1px solid var(--line); }
.theme-psg tbody tr:hover { box-shadow: inset 3px 0 0 var(--accent); background: oklch(1 0 0 / 4%); }
.theme-psg a { color: var(--accent-2); text-underline-offset: 3px; text-decoration-color: oklch(0.575 0.213 29.6 / 70%); }
.theme-psg a:hover { text-decoration-color: oklch(1 0 0); text-decoration-thickness: 2px; }
.theme-psg ::selection { background: oklch(0.575 0.213 29.6); color: oklch(1 0 0); }
.theme-psg input:focus-visible, .theme-psg select:focus-visible, .theme-psg textarea:focus-visible { outline: 2px solid oklch(1 0 0 / 80%); outline-offset: 1px; }
.theme-psg kbd { background: oklch(0.17 0.045 264); border: 1px solid var(--line); border-radius: var(--radius-sm); padding: 0.1em 0.45em; font-family: var(--font-mono); }
.theme-psg ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-psg ::-webkit-scrollbar-track { background: oklch(0.17 0.045 264); }
.theme-psg ::-webkit-scrollbar-thumb { background: oklch(0.42 0.16 28); border-radius: 5px; border: 2px solid oklch(0.17 0.045 264); }
.theme-psg ::-webkit-scrollbar-thumb:hover { background: oklch(0.52 0.19 28); }
.theme-psg .label-caps { color: var(--accent-2); }
/* the Hechter band, vertical, as a border treatment */
.theme-psg .themed-border { border-image: linear-gradient(180deg, #0b1730 0 30%, #ffffff 30% 40%, oklch(0.575 0.213 29.6) 40% 60%, #ffffff 60% 70%, #0b1730 70%) 1; }
.theme-psg button:active { transform: translateY(1px); }

/* alt mode: away kit (2026-27 real kit / NBA Association Edition) */
.theme-psg.alt-mode {
  --bg: oklch(0.985 0 0);
  --surface: oklch(1.000 0 0);
  --surface-2: oklch(0.955 0.006 264.5);
  --fg: oklch(0.261 0.081 264.8);
  --fg-muted: oklch(0.564 0.045 269.5);
  --accent: oklch(0.327 0.108 266.0);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.575 0.213 29.6);
  --line: oklch(0.915 0.010 261.8);
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  background-image: linear-gradient(90deg, transparent 0 46%, oklch(0.45 0.18 25 / 20%) 46% 50%, oklch(0.35 0.12 265 / 20%) 50% 54%, transparent 54%), repeating-linear-gradient(90deg, oklch(0.3 0.08 265 / 4%) 0 2px, transparent 2px 8px);
  background-size: 100% 420px, 16% 420px; background-repeat: no-repeat; background-position: top center, top center;
}
.theme-psg.alt-mode h1, .theme-psg.alt-mode h2 { color: #10214b; }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
